(() => {
 'use strict';
 const D=window.OP_DATA;
 if(!D){document.getElementById('main').textContent='O acervo não foi gerado. Execute iniciar-portal.ps1 ou python portal/build.py.';return;}
 const allDocs=D.documents, byId=new Map(allDocs.map(d=>[d.id,d]));
 const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const norm=s=>String(s).normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
 allDocs.forEach(d=>{if(d.search==null)d.search=norm(d.title+' '+d.body);});
 const store={get(k,f){try{const v=JSON.parse(localStorage.getItem(k)||'null');return v??f;}catch{return f;}},set(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true;}catch{return false;}}};
 const paths={compass:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z M12 9v6 M9 12h6',home:'m3 10 9-7 9 7 M5 9v12h14V9 M9 21v-7h6v7',book:'M12 5c-3-2-6-2-9-1v15c3-1 6-1 9 1 3-2 6-2 9-1V4c-3-1-6-1-9 1Z M12 5v15',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2V5Z M9 3v16 M15 5v16',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-4 M16 3a4 4 0 0 1 0 8',calendar:'M4 5h16v16H4V5Z M4 10h16 M8 3v4 M16 3v4',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z M3 12h18 M12 3c5 5 5 13 0 18-5-5-5-13 0-18Z',tools:'m14 6 4 4 M5 21l-2-2 9-9 2 2-9 9Z M14 3l7 7-3 3-7-7 3-3Z',folder:'M3 5h7l2 3h9v12H3V5Z',star:'m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6Z',search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0Z',arrow:'M5 12h14 M14 7l5 5-5 5',chevron:'m9 5 7 7-7 7',lock:'M5 10h14v11H5V10Z M8 10V7a4 4 0 0 1 8 0v3',refresh:'M20 8a8 8 0 1 0 1 7 M20 3v5h-5',menu:'M3 6h18 M3 12h18 M3 18h18',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0Z M12 10v4 M10 12h4',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z',spark:'m12 3 2 6 6 3-6 2-2 7-2-7-7-2 7-3 2-6Z',anchor:'M12 7v14 M8 3h8 M3 13c0 9 18 9 18 0 M1 15l2-2 2 2 M19 15l2-2 2 2',file:'M5 3h9l5 5v13H5V3Z M14 3v5h5 M8 12h8 M8 16h8',check:'m5 12 4 4L19 6',circle:'M20 12a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',copy:'M8 8h12v13H8V8Z M16 8V3H3v13h5',dice:'M4 4h16v16H4V4Z M8.5 8.5h.01 M15.5 8.5h.01 M12 12h.01 M8.5 15.5h.01 M15.5 15.5h.01',moon:'M20 14.5A8 8 0 0 1 9.5 4a8 8 0 1 0 10.5 10.5Z',sun:'M12 4V2 M12 22v-2 M4 12H2 M22 12h-2 M5.6 5.6 4.2 4.2 M19.8 19.8l-1.4-1.4 M5.6 18.4l-1.4 1.4 M19.8 4.2l-1.4 1.4 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',swords:'M14.5 17.5 3 6V3h3l11.5 11.5 M13 19l6-6 M16 16l4 4 M19 21l2-2 M9.5 6.5 14 2h3v3l-4.5 4.5 M5 14l-2 2 M3 19l2 2',grid:'M3 3h8v8H3V3Z M13 3h8v8h-8V3Z M3 13h8v8H3v-8Z M13 13h8v8h-8v-8Z',flag:'M5 21V4 M5 4h12l-2 4 2 4H5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',list:'M8 6h13 M8 12h13 M8 18h13 M3 6h.01 M3 12h.01 M3 18h.01',news:'M4 5h13v13a2 2 0 0 0 2 2H6a2 2 0 0 1-2-2V5Z M17 9h3v9a2 2 0 0 1-2 2 M7 9h7 M7 13h7 M7 16h4',mic:'M12 3a3 3 0 0 0-3 3v6a3 3 0 0 0 6 0V6a3 3 0 0 0-3-3Z M5 11a7 7 0 0 0 14 0 M12 18v3 M8 21h8'};
 const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
 const cats={regras:{name:'Biblioteca de regras',short:'Regras',icon:'book',description:'O sistema OP RPG, organizado para consultar e jogar. Fontes, opções e dúvidas preservadas.'},campanha:{name:'Nossa campanha',short:'Campanha',icon:'map',description:'Premissa, história, aventuras e decisões que dão forma à nossa jornada.'},personagens:{name:'Tripulação e personagens',short:'Personagens',icon:'users',description:'Histórias, fichas e vínculos. Cada personagem começa com uma ideia.'},sessoes:{name:'Diário das sessões',short:'Sessões',icon:'calendar',description:'Preparação, acontecimentos e memórias de cada encontro na mesa.'},mundo:{name:'Um mundo por descobrir',short:'Mundo e elenco',icon:'globe',description:'Ilhas, facções, NPCs, inimigos e lugares que cruzam o nosso caminho.'},oficina:{name:'Oficina de criação',short:'Oficina',icon:'tools',description:'Do conceito à ficha: procedimentos, modelos e mecânicas para criar o próximo capítulo.'},projeto:{name:'Por trás da aventura',short:'Projeto e memória',icon:'folder',description:'O mapa do projeto, auditorias, modelos, ferramentas e tudo que outra IA precisa para continuar.'}};
 /* Grupos da biblioteca de regras, calculados no build a partir do nome de cada nota. */
 const groups={criacao:{name:'Criação de personagem',short:'Criação',icon:'users'},jogo:{name:'Regras de jogo',short:'Regras de jogo',icon:'shield'},guia:{name:'Guia do Narrador',short:'Guia do Narrador',icon:'map'},bestiario:{name:'Bestiário (Manual dos Inimigos)',short:'Bestiário',icon:'target'}};
 const bookNames={LJ:'Livro do Jogador',GN:'Guia do Narrador',MI:'Manual dos Inimigos',LA:'Livro das Akuma',RT:'Resumo de Técnicas'};

 /* Prévia do jogador: o mestre vê só as notas da lista dos jogadores. É filtro de interface, não controle de acesso. */
 let preview=false;try{preview=D.audience!=='player'&&sessionStorage.getItem('oprpg-player-preview')==='1';}catch{}
 const playerSet=new Set(D.playerNotes||[]);
 const isPlayer=()=>D.audience==='player'||preview;
 const playerCats=['regras','mundo','personagens'];
 let docs=allDocs;
 const crew=()=>(D.characters||[]).filter(c=>!isPlayer()||docs.some(d=>d.id===c.sheet));
 const applyPreview=()=>{docs=preview?allDocs.filter(d=>playerSet.has(d.id)):allDocs;};applyPreview();

 let favorites=store.get('oprpg-favorites',[]);if(!Array.isArray(favorites))favorites=[];
 const link=(id,anchor)=>id?'#note/'+id+(anchor?'/'+anchor:''):'#library/regras';
 const shortcut=n=>link(D.shortcuts[n]);
 const byStem=stem=>docs.find(d=>d.path.split('/').pop().replace(/\.md$/,'')===stem);
 const toast=t=>{$('toast').textContent=t;$('toast').classList.add('visible');setTimeout(()=>$('toast').classList.remove('visible'),2600);};
 const journalCount=()=>(D.newspapers||[]).filter(e=>!isPlayer()||e.published).length;
 const count=c=>c==='personagens'?crew().length:docs.filter(d=>d.category===c).length;
 const groupCount=g=>docs.filter(d=>d.category==='regras'&&d.group===g).length;
 const status=d=>norm(d.meta.status||'');
 const sourceLabel=d=>d.book?`${d.book}${d.pages?' p. '+d.pages:''}`:'';
 function badge(d){if(d.path.startsWith('99 Templates/'))return '<span class="tag">Modelo</span>';if(d.category==='regras')return `<span class="tag">${esc(groups[d.group]?.short||'Regras')}${d.chapter?' · '+esc(d.chapter):''}</span>`;const canon=norm(d.meta.canon||'');if(canon==='decidido')return '<span class="tag">Decidido</span>';if(canon==='rascunho'||canon==='misto')return '<span class="tag proposal">'+(canon==='misto'?'Decidido e rascunho':'Rascunho')+'</span>';if(canon==='em aberto')return '<span class="tag proposal">Em aberto</span>';if(/proposta|teste|criacao|planejad|incompleto|desenvolvimento/.test(status(d))||d.meta.uso==='teste-de-criacao')return '<span class="tag proposal">Em construção</span>';if(status(d)==='realizada')return '<span class="tag">Realizada</span>';return '<span class="tag">Acervo</span>';}

 function navItem(href,ic,label,active,countText='',extra=''){return `<a href="${href}" class="nav-item ${active?'active':''} ${extra}">${icon(ic)}${label}${countText!==''?`<span class="nav-count">${countText}</span>`:''}</a>`;}
 function sidebar(active){const player=isPlayer();const regrasOpen=active==='regras'||String(active).startsWith('g:');
  const sub=Object.entries(groups).filter(([g])=>groupCount(g)).map(([g,v])=>`<a href="#library/regras/${g}" class="nav-sub ${active==='g:'+g?'active':''}">${v.short}<span class="nav-count">${groupCount(g)}</span></a>`).join('');
  $('sidebar').innerHTML=`<a href="#inicio" class="brand"><img class="brand-logo" src="logo-one-piece.svg" alt="" width="62" height="54"><div><strong>Diário de bordo</strong><small>ONE PIECE · OP RPG</small></div></a>${navItem('#inicio','home','Visão geral',active==='inicio')}${player?navItem('#comece','flag','Comece aqui',active==='comece')+navItem('#referencia','list','Referência rápida',active==='referencia'):''}<div class="nav-label">Explore a campanha</div>${navItem('#library/regras','book','Regras',regrasOpen&&active==='regras',count('regras'))}<div class="nav-subs ${regrasOpen?'open':''}">${sub}</div>${navItem('#jornal','news','Jornal',active==='jornal',journalCount())}${window.OP_MAP&&D.worldMap?navItem('#mapa','map','Mapa do mundo',active==='mapa'):''}${player&&window.OP_CREATOR?navItem('#criar-personagem','spark','Criar personagem',active==='criar'):''}${player&&window.OP_FORGE?navItem('#criadores','anchor','Criadores',active==='criadores'):''}${player?navItem('#library/personagens','users','Tripulação',active==='personagens',count('personagens'))+navItem('#library/mundo','globe','Mundo',active==='mundo',count('mundo')):''}${player?'':Object.entries(cats).slice(1,5).map(([k,v])=>navItem('#library/'+k,v.icon,v.short,active===k,k==='sessoes'?D.stats.sessions:count(k))).join('')}${player?'':`<div class="nav-label">Mesa</div>${navItem('#mesa','grid','Tela do mestre',active==='mesa')}${window.OP_CREATOR?navItem('#fichas','users','Fichas na mesa',active==='fichas'):''}${navItem('#iniciativa','swords','Iniciativa',active==='iniciativa')}${navItem('#bestiario','target','Bestiário',active==='bestiario',(D.bestiary||[]).length)}${navItem('#gravacoes','mic','Gravações',active==='gravacoes',(D.recordings||[]).length)}<div class="nav-label">Caderno do mestre</div>${['oficina','projeto'].map(k=>navItem('#library/'+k,cats[k].icon,cats[k].short,active===k)).join('')}${window.OP_FORGE?navItem('#criadores','anchor','Criadores',active==='criadores'):''}`}${navItem('#favoritos','star','Meus favoritos',active==='favoritos',favorites.filter(x=>byId.has(x)).length)}${D.audience==='player'?`<a class="nav-item access-link" href="mestre/" title="Abre a tela de senha do portal do mestre">${icon('lock')}Entrar como mestre</a>`+(window.OP_GATE?'<button type="button" class="nav-item access-link" data-logout>Sair da área dos jogadores</button>':''):preview?'<button type="button" class="nav-item access-link" data-preview-off>Sair da prévia do jogador</button>':'<a class="nav-item access-link" href="#acessos">♜ Áreas de acesso</a>'}<div class="side-bottom"><div class="voyage">${player?'<small>MANUAL DA TRIPULAÇÃO</small><h4>East Blue</h4><p>Regras para criar e jogar</p>':'<small>NOSSA PRIMEIRA JORNADA</small><h4>East Blue</h4><p>3 jogadores · níveis 1 a 5</p><div class="voyage-track"><span></span></div><p>Preparando a primeira aventura</p>'}</div><div class="side-footer">${icon(player?'book':'lock')}${D.audience==='player'?'Área dos jogadores':preview?'Prévia do jogador':'Acervo do mestre'}</div></div>`;}
 function crumb(label,parent){$('breadcrumbs').innerHTML=`<a href="#inicio">Campanha OP RPG</a>${parent?icon('chevron')+`<a href="${parent[1]}">${esc(parent[0])}</a>`:''}${icon('chevron')}<span class="current">${esc(label)}</span>`;}
 function header(title,desc,eyebrow='O diário da nossa jornada'){return `${preview?`<div class="preview-banner">${icon('eye')}<span>Prévia do jogador: você está vendo só as ${playerSet.size} notas liberadas para a mesa.</span><button type="button" class="btn btn-light" data-preview-off>Sair da prévia</button></div>`:''}<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div><span class="date-tag">${icon('calendar')}East Blue · capítulo inicial</span></div>`;}
 function docCard(d){const foot=sourceLabel(d)||d.meta.fonte||cats[d.category].short;return `<a href="${link(d.id)}" class="document-card"><div class="doc-top">${icon(d.category==='regras'?groups[d.group]?.icon||'book':cats[d.category].icon)}${badge(d)}</div><h3>${esc(d.title)}</h3><p>${esc(d.summary)}</p><div class="doc-foot"><span>${esc(foot)}</span>${icon('arrow')}</div></a>`;}
 const ruleFeatures=[['Atributos e Testes - Referencia','Atributos e testes','Perícias, salvaguardas e proficiência','target'],['Combate - Referencia','Combate e ações','Ataques, turnos e condições','shield'],['Especies - Referencia','Espécies e origens','Humanos, minks e muito mais','users'],['Estilos e Tecnicas - Estrutura','Estilos e técnicas','Encontre seu jeito de lutar','spark'],['Akuma no Mi - Regras e Criacao','Akuma no Mi e poderes','Frutas, efeitos e possibilidades','globe'],['Equipamentos - Referencia','Equipamentos e navios','Armas, ferramentas e tesouros','anchor']];
 const ruleGrid=()=>`<div class="rule-grid">${ruleFeatures.map(([id,name,desc,i])=>`<a class="rule-card" href="${shortcut(id)}"><div class="rule-icon">${icon(i)}</div><div><h3>${name}</h3><p>${desc}</p></div><span class="arrow">${icon('arrow')}</span></a>`).join('')}</div>`;

 /* ---------- Página inicial ---------- */
 function home(){if(isPlayer())return playerHome();sidebar('inicio');crumb('Visão geral');document.title='Diário de bordo · OP RPG';
  const prep=byId.get(D.shortcuts['Preparacao Primeira Sessao']);const firstPc=(D.characters||[])[0];
  const quick=[['#criar-personagem','spark','Criar personagem','Ficha guiada do nível 1 ao 20'],['#criadores','anchor','Criadores','Técnicas, frutas, navios, armas e itens'],['#mesa','grid','Tela do mestre','Ações, condições e CDs'],['#iniciativa','swords','Iniciativa','Turnos, PV e condições'],['#bestiario','target','Bestiário',`${(D.bestiary||[]).length} inimigos do Manual`],['#library/regras','book','Biblioteca','Regras em lista, com filtros'],['#library/oficina','tools','Oficina','Inimigos, ilhas e itens'],['#jornal','news',"Jornal News Coo's",'Edições e cartazes de recompensa'],[shortcut('00 Biblia do Mundo'),'globe','Bíblia do mundo','Cânone, segredos e questões']];
  $('main').innerHTML=header('Bem-vindo a bordo, mestre.','Seu mundo, suas histórias e as regras que tornam tudo possível.')+`<section class="prep-board"><article class="prep-card prep-next"><div class="eyebrow">PRÓXIMA SESSÃO</div><h2>Estreia no East Blue</h2><p class="prep-when">${icon('calendar')}Dia e horário a confirmar</p><p>${esc(prep?.summary||'A preparação da primeira sessão ainda não foi registrada.')}</p>${prep?`<a class="btn btn-primary" href="${link(prep.id)}">Abrir a preparação ${icon('arrow')}</a>`:''}</article><article class="prep-card"><div class="eyebrow">ANTES DE LEVANTAR AS VELAS</div><ul class="checklist"><li>${icon('check')}Regras e fontes organizadas</li><li>${icon('check')}Oficina de criação disponível</li><li class="pending">${icon('circle')}Fechar as fichas e os vínculos dos 3 jogadores</li><li>${icon('check')}Base do mundo, tema e vilões registrados</li><li class="pending">${icon('circle')}Definir ilha inicial e a primeira aventura</li><li class="pending">${icon('circle')}Preparar Foundry e Discord</li></ul><a class="text-link" href="${shortcut('estado-do-projeto')}">Ver o estado do projeto ${icon('arrow')}</a></article><article class="prep-card"><div class="eyebrow">TRIPULAÇÃO</div>${(D.characters||[]).map(c=>`<a class="crew-row" href="${link(c.sheet)}"><span class="crew-sigil">${icon('target')}</span><span><strong>${esc(c.name)}</strong><small>${esc(c.species)} · ${esc(c.style)} · nível ${esc(c.level)} · ${esc(c.status)}</small></span></a>`).join('')}<p class="soft-note">3 jogadores previstos, nenhuma ficha definitiva aprovada.</p><a class="text-link" href="#criar-personagem">Criar uma ficha ${icon('arrow')}</a></article></section><section class="quick-grid">${quick.map(([h,i,t,s])=>`<a class="quick-card" href="${h}">${icon(i)}<span><strong>${t}</strong><small>${s}</small></span></a>`).join('')}</section><section class="hero hero--compact" aria-label="A primeira jornada"><img class="hero-art" src="pirate-hero.svg" alt="Ilustração de um navio pirata com uma bandeira de chapéu de palha, navegando por um mar azul; imagem temática, sem representar eventos da campanha"><div class="hero-content"><div class="eyebrow">CADA GRANDE HISTÓRIA COMEÇA AQUI</div><h2>Um mar de aventuras. Uma história <em>nossa.</em></h2><a href="${shortcut('Campanha - Visao geral')}" class="btn btn-primary">Explorar a campanha ${icon('arrow')}</a></div></section><div class="stat-grid"><a class="stat" href="#library/regras"><div class="stat-icon">${icon('book')}</div><div><strong>${D.stats.rules}</strong><span>notas de regras</span></div></a><a class="stat" href="#library/personagens"><div class="stat-icon">${icon('users')}</div><div><strong>${D.stats.playersPlanned||3}</strong><span>jogadores previstos</span></div></a><a class="stat" href="#library/sessoes"><div class="stat-icon">${icon('calendar')}</div><div><strong>${D.stats.sessions}</strong><span>${D.stats.sessions===1?'sessão realizada':'sessões realizadas'}</span></div></a><a class="stat" href="${shortcut('Fontes e precedencia')}"><div class="stat-icon">${icon('folder')}</div><div><strong>${D.stats.books||5}</strong><span>livros de referência</span></div></a></div><section><div class="section-head"><div><h2>Sua biblioteca de regras</h2><p>Menos tempo procurando. Mais tempo criando.</p></div><a class="text-link" href="#library/regras">Ver tudo ${icon('arrow')}</a></div>${ruleGrid()}</section><div class="bottom-grid"><section><div class="section-head"><h2>Uma história começa a surgir</h2><a href="#library/personagens" class="text-link">Ver personagens ${icon('arrow')}</a></div>${firstPc?`<a href="${link(firstPc.sheet)}" class="character-card"><div class="character-sigil">${icon('target')}</div><div><span class="tag proposal">${esc(firstPc.status)}</span><h3>${esc(firstPc.name)}</h3><p>${esc(firstPc.concept)}</p><div class="character-mini"><span>${esc(firstPc.species)}</span><span>${esc(firstPc.style)} · nível ${esc(firstPc.level)}</span></div></div></a>`:`<a href="#criar-personagem" class="character-card"><div class="character-sigil">${icon('spark')}</div><div><span class="tag proposal">AGUARDANDO</span><h3>Nenhuma ficha ainda</h3><p>As três fichas dos jogadores ainda não foram criadas. Comece pela Oficina.</p></div></a>`}</section><section><div class="section-head"><h2>Caderno do projeto</h2><a href="${shortcut('estado-do-projeto')}" class="text-link">Continuar o trabalho ${icon('arrow')}</a></div><div class="activity"><div class="activity-row"><span class="activity-dot"></span><div><strong>Conhecimento que acompanha a campanha</strong><small>${D.stats.notes} notas conectadas, com fontes e pendências.</small></div></div><div class="activity-row"><span class="activity-dot"></span><div><strong>Uma oficina para as próximas ideias</strong><small>Inimigos, ilhas, itens, frutas e fichas por descrição.</small></div></div><div class="activity-row"><span class="activity-dot"></span><div><strong>Uma memória para cada encontro</strong><small>Sessões e transcrições terão seu lugar aqui.</small></div></div></div></section></div>`;}

 function playerHome(){const worldDoc=docs.find(d=>d.path==='03 Mundo/Conhecimento Comum - O que o mundo sabe.md');sidebar('inicio');crumb('Regras dos jogadores');document.title='Regras da tripulação · OP RPG';
  $('main').innerHTML=header('Prepare-se para zarpar.','O livro de consulta da tripulação, do primeiro atributo à próxima aventura.','ONE PIECE · OP RPG')+`<section class="hero hero--compact"><img class="hero-art" src="pirate-hero.svg" alt="Navio pirata ilustrado sobre um mar azul"><div class="hero-content"><div class="eyebrow">O MAR ESTÁ CHAMANDO</div><h2>Grandes sonhos. Uma só <em>tripulação.</em></h2><a class="btn btn-primary" href="#library/regras">Abrir biblioteca ${icon('book')}</a></div></section><section class="quick-grid quick-grid--two">${window.OP_CREATOR?`<a class="quick-card quick-card--feature" href="#criar-personagem">${icon('spark')}<span><strong>Criar personagem</strong><small>Monte sua ficha passo a passo, suba de nível e mande o link para o mestre.</small></span></a>`:''}${window.OP_FORGE?`<a class="quick-card quick-card--feature" href="#criadores">${icon('anchor')}<span><strong>Criadores</strong><small>Técnicas, Akuma no Mi, navios, armas e itens com as regras do livro.</small></span></a>`:''}<a class="quick-card quick-card--feature" href="#comece">${icon('flag')}<span><strong>Comece aqui</strong><small>A ordem de leitura para criar seu personagem, passo a passo.</small></span></a><a class="quick-card quick-card--feature" href="#referencia">${icon('list')}<span><strong>Referência rápida</strong><small>Ações, condições e testes para consultar durante a sessão.</small></span></a>${worldDoc?`<a class="quick-card quick-card--feature" href="${link(worldDoc.id)}">${icon('globe')}<span><strong>O que o mundo sabe</strong><small>O mundo como um morador do East Blue o conhece.</small></span></a>`:''}<a class="quick-card quick-card--feature" href="#library/personagens">${icon('users')}<span><strong>Fichas da tripulação</strong><small>${crew().length?crew().length+(crew().length===1?' ficha liberada':' fichas liberadas'):'As fichas aparecem aqui quando forem liberadas.'}</small></span></a>${(()=>{const e=(D.newspapers||[]).filter(x=>x.published).sort((a,b)=>b.number-a.number)[0];return `<a class="quick-card quick-card--feature" href="#jornal">${icon('news')}<span><strong>Jornal News Coo's</strong><small>${e?'Última edição: '+esc(e.headline):'Notícias do mundo e cartazes de recompensa da tripulação.'}</small></span></a>`;})()}</section><section class="section-gap"><div class="section-head"><h2>Seu manual de bordo</h2><span>${D.stats.rules} referências</span></div><div class="group-row">${Object.entries(groups).filter(([g])=>groupCount(g)).map(([g,v])=>`<a class="group-card" href="#library/regras/${g}">${icon(v.icon)}<strong>${v.name}</strong><small>${groupCount(g)} notas</small></a>`).join('')}</div>${ruleGrid()}</section>`;}

 /* ---------- Comece aqui ---------- */
 const startSteps=[['Escolha a espécie','Origem, tamanho, deslocamento e traços de nascença.',['Especies - Referencia']],['Distribua os atributos','Os seis atributos e como os modificadores entram nos testes.',['Atributos e Testes - Referencia']],['Escolha o estilo de luta','O estilo define PV, salvaguardas, ataques e técnicas iniciais.',['Estilos e Tecnicas - Estrutura']],['Escolha a profissão','Graduação inicial, ferramentas e a perícia especial.',['Profissoes - Referencia']],['Escolha o antecedente','De onde o personagem vem e o que ele ganha com isso.',['Antecedentes - Catalogo']],['Habilidade básica, singularidades e defeitos','O que torna o personagem único, com o preço de cada vantagem.',['Habilidades Basicas - Referencia','Singularidades - Catalogo','Defeitos - Catalogo']],['Treinamentos','Pontos de treinamento e o que eles compram.',['Treinamento - Regras Gerais','Treinamentos Gerais - Catalogo']],['Equipamento','Armas, munição e o que levar na mochila.',['Equipamentos - Referencia']],['Akuma no Mi, se o mestre permitir','Começar com fruta depende do acordo da mesa.',['Akuma no Mi - Fruta Inicial e Categorias']]];
 function startHere(){sidebar('comece');crumb('Comece aqui');document.title='Comece aqui · OP RPG';
  const links=stems=>stems.map(byStem).filter(Boolean).map(d=>`<a href="${link(d.id)}" class="step-link">${esc(d.title)} ${d.pages?`<small>p. ${esc(d.pages)}</small>`:''}</a>`).join('');
  $('main').innerHTML=header('Comece aqui.','A ordem de leitura para criar o seu personagem de nível 1. Leve as dúvidas para o mestre antes da primeira sessão.','Manual da tripulação')+(window.OP_CREATOR?`<p><a class="btn btn-primary" href="#criar-personagem">Criar minha ficha no portal ${icon('arrow')}</a></p>`:'')+`<ol class="start-steps">${startSteps.map(([t,s,st])=>`<li><div><h3>${t}</h3><p>${s}</p><div class="step-links">${links(st)||'<span class="soft-note">Nota ainda não liberada para os jogadores.</span>'}</div></div></li>`).join('')}</ol><section class="section-gap"><div class="section-head"><h2>Para a primeira sessão</h2></div><div class="step-links step-links--wide">${links(['Combate - Referencia','Tecnicas e Condicoes - Referencia','Aventura - Referencia'])}<a class="step-link" href="#referencia">Referência rápida ${icon('arrow')}</a></div></section>`;}

 /* ---------- Biblioteca ---------- */
 function bookStrip(){const books=[['Livro do Jogador','1.5.7 · 293 páginas','Livro do Jogador - Referencia'],['Guia do Narrador','1.2 · 170 páginas','Guia do Narrador - Referencia'],['Manual dos Inimigos','Playtest 2.0 · 51 páginas','Manual dos Inimigos - Referencia'],['Criação de técnicas','Resumo 1.5 · 28 páginas','Resumo de Tecnicas - Comparacao'],['Livro das Akuma','124 entradas · 8 páginas','Akuma no Mi - Catalogo']];return `<div class="book-strip">${books.map(([t,v,n],i)=>{let d=byStem(n);return d?`<a class="book" href="${link(d.id)}"><small>FONTE 0${i+1}</small><strong>${t}</strong><span>${v}</span></a>`:'';}).join('')}</div>`;}
 let libState={q:'',book:'',chapter:''};
 function library(cat,sub,selectedId){if(isPlayer()&&!playerCats.includes(cat))return notFound();if(cat==='personagens')return characters();if(!cats[cat])return notFound();if(cat==='regras')return rulesLibrary(sub,selectedId);
  sidebar(cat);crumb(cats[cat].short);document.title=cats[cat].name+' · Diário de bordo';let intro=cat==='oficina'?workshopBanner():'';
  if(cat==='sessoes'&&!D.stats.sessions)intro=`<section class="empty-state">${icon('calendar')}<h2>A primeira página ainda está em branco.</h2><p>Nenhuma sessão realizada foi registrada. Depois da estreia, este será o lugar de revisitar encontros, decisões e consequências.</p><a href="${shortcut('Preparacao Primeira Sessao')}" class="btn btn-light">Preparar a primeira sessão ${icon('arrow')}</a></section>`;
  if(cat==='mundo')intro=isPlayer()?'<div class="note-tip">O que a tripulação sabe sobre o mundo. Novas ilhas, pessoas e notícias entram aqui conforme a campanha avança.</div>':`<div class="note-tip">A base do universo está na <a href="${shortcut('00 Biblia do Mundo')}"><strong>Bíblia do mundo ↗</strong></a>. Decidido é cânone, Rascunho é base aberta a mudanças e Em aberto ainda não foi definido. Segredos do mestre ficam só neste acervo. Ilhas, NPCs e facções do East Blue aparecerão aqui conforme forem registrados.</div>`;
  if(cat==='projeto')intro=`<div class="note-panel"><div class="eyebrow">COMECE POR AQUI</div><h3>Um projeto que outra IA pode continuar.</h3><p>O estado atual, as fontes, os limites e os próximos passos estão nos próprios arquivos do projeto. As auditorias e as pendências de regras também ficam aqui.</p><a class="btn btn-light" href="${shortcut('estado-do-projeto')}">Ler o estado atual ${icon('arrow')}</a></div>`;
  $('main').innerHTML=header(cats[cat].name,cats[cat].description,'O acervo da campanha')+intro+`<div class="library-tools"><div class="filter-search">${icon('search')}<input id="library-search" placeholder="Buscar em ${esc(cats[cat].short.toLowerCase())}…" aria-label="Filtrar notas desta seção"></div><select id="type-filter" aria-label="Filtrar por tipo"><option value="">Todos os tipos</option></select><select id="sort-filter" aria-label="Ordenar notas"><option value="title">Ordem alfabética</option><option value="source">Por fonte</option></select></div><div id="result-count" class="result-count"></div><div id="document-list" class="document-grid"></div>`;
  const subset=docs.filter(d=>d.category===cat);const types=[...new Set(subset.map(d=>d.meta.tipo).filter(Boolean))].sort();$('type-filter').innerHTML+=types.map(t=>`<option value="${esc(t)}">${esc(t.replaceAll('-',' '))}</option>`).join('');
  function update(){const q=norm($('library-search').value).trim().split(/\s+/).filter(Boolean),type=$('type-filter').value;const list=subset.filter(d=>(!type||d.meta.tipo===type)&&q.every(x=>d.search.includes(x)));list.sort((a,b)=>($('sort-filter').value==='source'?String(a.meta.fonte||'').localeCompare(String(b.meta.fonte||''),'pt-BR'):0)||a.title.localeCompare(b.title,'pt-BR'));$('result-count').textContent=`${list.length} ${list.length===1?'nota encontrada':'notas encontradas'}${q.length?' para esta busca':''}`;$('document-list').innerHTML=list.map(docCard).join('')||'<div class="empty-state"><h2>Nada por aqui com esse filtro.</h2><p>Tente outro termo ou selecione todos os tipos.</p></div>';}
  ['library-search','type-filter','sort-filter'].forEach(n=>$(n).addEventListener(n==='library-search'?'input':'change',update));update();}

 /* Biblioteca de regras no padrão das páginas do 5etools: lista filtrável à esquerda, nota aberta à direita. */
 function rulesLibrary(group,selectedId){if(group&&!groups[group])group='';sidebar(group?'g:'+group:'regras');crumb(group?groups[group].short:'Regras',group?['Regras','#library/regras']:null);document.title=(group?groups[group].name:cats.regras.name)+' · Diário de bordo';
  const subset=docs.filter(d=>d.category==='regras');const chapters=[...new Set(subset.filter(d=>d.group==='guia').map(d=>d.chapter).filter(Boolean))].sort();const books=[...new Set(subset.map(d=>d.book).filter(Boolean))];
  const tip=isPlayer()?'<div class="note-tip">Referências do Livro do Jogador e dos suplementos de regras. Consulte cada fonte e confirme interpretações com o mestre.</div>':`<div class="note-tip">Notas mantêm fontes e versões. Dúvidas e diferenças entre livros estão em <a href="${shortcut('Pendencias e Divergencias')}"><strong>pendências e divergências ↗</strong></a>.</div>`;
  $('main').innerHTML=header(group?groups[group].name:cats.regras.name,cats.regras.description,'O acervo da campanha')+(isPlayer()?'':bookStrip())+tip+`<div class="lib-layout"><div class="lib-list"><div class="library-tools"><div class="filter-search">${icon('search')}<input id="library-search" placeholder="Filtrar por nome ou conteúdo…" aria-label="Filtrar regras" value="${esc(libState.q)}"></div>${books.length>1?`<select id="book-filter" aria-label="Filtrar por livro"><option value="">Todos os livros</option>${books.map(b=>`<option value="${b}" ${libState.book===b?'selected':''}>${esc(bookNames[b]||b)}</option>`).join('')}</select>`:''}${group==='guia'?`<select id="chapter-filter" aria-label="Filtrar por capítulo do Guia"><option value="">Todos os capítulos</option>${chapters.map(c=>`<option ${libState.chapter===c?'selected':''}>${esc(c)}</option>`).join('')}</select>`:''}</div><div class="pill-row">${[['','Tudo',subset.length],...Object.entries(groups).map(([g,v])=>[g,v.short,groupCount(g)]).filter(x=>x[2])].map(([g,t,n])=>`<a class="pill ${g===(group||'')?'active':''}" href="#library/regras${g?'/'+g:''}">${t} <small>${n}</small></a>`).join('')}</div><div id="result-count" class="result-count"></div><div class="lib-table-wrap"><table class="lib-table"><thead><tr><th>Nome</th><th>Grupo</th><th>Fonte</th></tr></thead><tbody id="lib-rows"></tbody></table></div></div><aside class="lib-pane" id="lib-pane" aria-live="polite"></aside></div>`;
  let list=[],current=selectedId&&byId.has(selectedId)?selectedId:null;
  function update(){libState.q=$('library-search').value;libState.book=$('book-filter')?.value||'';libState.chapter=$('chapter-filter')?.value||'';const q=norm(libState.q).trim().split(/\s+/).filter(Boolean);
   list=subset.filter(d=>(!group||d.group===group)&&(!libState.book||d.book===libState.book)&&(!libState.chapter||d.chapter===libState.chapter)&&q.every(x=>d.search.includes(x))).sort((a,b)=>(q.length?(norm(b.title).includes(q[0])-norm(a.title).includes(q[0])):0)||a.title.localeCompare(b.title,'pt-BR'));
   $('result-count').textContent=`${list.length} ${list.length===1?'nota':'notas'}${q.length?' para esta busca':''} · ↑ ↓ para navegar, Enter para abrir`;
   $('lib-rows').innerHTML=list.map(d=>`<tr data-id="${d.id}" class="${d.id===current?'selected':''}" tabindex="-1"><td><a href="${link(d.id)}">${esc(d.title)}</a></td><td>${esc(groups[d.group]?.short||'')}${d.chapter?`<small>${esc(d.chapter)}</small>`:''}</td><td class="nowrap">${esc(sourceLabel(d))}</td></tr>`).join('')||'<tr><td colspan="3" class="empty-row">Nada encontrado. Tente outro termo ou outro grupo.</td></tr>';
   if(!current||!list.some(d=>d.id===current))current=list[0]?.id||null;showPane();}
  function showPane(){const d=byId.get(current);document.querySelectorAll('#lib-rows tr').forEach(r=>r.classList.toggle('selected',r.dataset.id===current));const pane=$('lib-pane');if(!d){pane.innerHTML='<div class="empty-state"><p>Escolha uma nota na lista.</p></div>';return;}
   const fav=favorites.includes(d.id);pane.innerHTML=`<div class="pane-head"><div class="article-meta">${badge(d)}${d.book?`<span class="tag gm">${esc(bookNames[d.book]||d.book)}${d.pages?' · p. '+esc(d.pages):''}</span>`:''}</div><h2>${esc(d.title)}</h2><div class="pane-actions"><a class="btn btn-primary" href="${link(d.id)}">Abrir página completa ${icon('arrow')}</a><button type="button" class="btn btn-light" data-fav="${d.id}">${icon('star')}${fav?'Favoritado':'Favoritar'}</button></div>${d.headings.length>2?`<nav class="pane-toc">${d.headings.filter(h=>!h.title.startsWith('#')).slice(0,14).map(h=>`<a href="#" data-pane-scroll="${h.id}">${esc(h.title.replace(/\s*\(p\..*?\)\s*$/,''))}</a>`).join('')}</nav>`:''}</div><div class="article-body pane-body">${d.html}</div>`;
   enhance(pane.querySelector('.pane-body'));pane.scrollTop=0;
   if(history.replaceState)history.replaceState(null,'',`#library/regras${group?'/'+group:'/tudo'}/${d.id}`);}
  $('lib-rows').addEventListener('click',e=>{const tr=e.target.closest('tr[data-id]');if(!tr)return;if(matchMedia('(max-width: 1100px)').matches)return;e.preventDefault();current=tr.dataset.id;showPane();});
  $('lib-pane').addEventListener('click',e=>{const s=e.target.closest('[data-pane-scroll]');if(s){e.preventDefault();const t=$('lib-pane').querySelector('#'+s.dataset.paneScroll);if(t)$('lib-pane').scrollTo({top:t.offsetTop-12,behavior:'smooth'});}const f=e.target.closest('[data-fav]');if(f){toggleFavorite(f.dataset.fav);showPane();}});
  $('library-search').addEventListener('keydown',e=>{if(!['ArrowDown','ArrowUp','Enter'].includes(e.key)||!list.length)return;e.preventDefault();const i=list.findIndex(d=>d.id===current);if(e.key==='Enter'){location.hash=link(current);return;}const n=Math.max(0,Math.min(list.length-1,i+(e.key==='ArrowDown'?1:-1)));current=list[n].id;showPane();document.querySelector(`#lib-rows tr[data-id="${current}"]`)?.scrollIntoView({block:'nearest'});});
  ['library-search','book-filter','chapter-filter'].forEach(n=>$(n)?.addEventListener(n==='library-search'?'input':'change',update));update();}

 function workshopBanner(){return `<section class="workshop-banner"><div><div class="eyebrow">DO CONCEITO À PRIMEIRA FICHA</div><h2>Seu próximo personagem começa aqui.</h2><p>Escolha espécie, heranças, estilo e profissão. As opções seguintes acompanham suas escolhas, com fontes e cálculos à vista.</p></div><a href="#criar-personagem" class="btn btn-primary">${icon('spark')}Criar personagem · nível 1</a></section>`;}
 function characters(){sidebar('personagens');crumb('Personagens');document.title='Personagens · Diário de bordo';$('main').innerHTML=header('Rostos da nossa história.','Uma entrada por personagem. Ficha, história e documentos reunidos.','Tripulação e personagens')+`${isPlayer()?'<div class="note-tip">As fichas aparecem aqui quando o mestre as libera para a mesa.</div>':'<div class="note-tip">Três jogadores previstos. As fichas definitivas ainda serão criadas e aprovadas. Para liberar uma ficha aos jogadores, inclua o caminho dela em <code>portal/player-manifest.json</code>.</div>'}<div class="section-head"><h2>${isPlayer()?'Fichas da tripulação':'Personagens em criação'}</h2>${isPlayer()?'':`<a class="btn btn-primary" href="#criar-personagem">${icon('spark')}Novo personagem</a>`}</div>${crew().length?'':`<section class="empty-state">${icon('users')}<h2>Nenhuma ficha liberada ainda.</h2><p>Quando as fichas forem aprovadas, cada personagem da tripulação aparece aqui.</p></section>`}<div class="entity-grid">${crew().map(c=>`<article class="wanted-card"><h2>WANTED</h2><div class="portrait" aria-label="Emblema de atirador; retrato ainda não definido">${icon('target')}</div><span class="tag proposal">${esc(c.status)}</span><h3>${esc(c.name)}</h3><p>${esc(c.concept)}</p><p>${esc(c.species)} · ${esc(c.style)} · nível ${c.level}<br>${esc(c.profession)}</p><div class="entity-links">${c.sheet?`<a class="btn btn-light" href="${link(c.sheet)}">Ficha</a>`:''}${c.dossier&&docs.some(d=>d.id===c.dossier)?`<a class="btn btn-light" href="${link(c.dossier)}">História e criação</a>`:''}${c.pdf?`<a class="btn btn-primary" href="${c.pdf}" target="_blank" rel="noopener">PDF</a>`:''}</div></article>`).join('')}</div>`;}
 function accessView(){if(isPlayer())return notFound();sidebar('acessos');crumb('Áreas de acesso');$('main').innerHTML=header('Cada tripulação, seu convés.','As regras dos jogadores ficam em outro acervo, separado dos segredos do mestre.','Acesso ao diário')+`<div class="access-grid"><section class="access-card"><span class="tag">TRIPULAÇÃO</span><h2>Área dos jogadores</h2><p>Regras, mundo e jornal para consultar durante a criação e o jogo. Aberto para a mesa no GitHub Pages.</p><a href="${esc(D.playerUrl)}" class="btn btn-primary" target="_blank" rel="noopener">Abrir regras dos jogadores ${icon('arrow')}</a><button type="button" class="btn btn-light" data-preview-on>${icon('eye')}Ver prévia aqui</button></section><section class="access-card private"><span class="tag proposal">SOMENTE O MESTRE</span><h2>A cabine do capitão</h2><p>Este portal guarda planejamento, fichas de teste, inimigos, memória e bastidores. No site, ele vai criptografado e só abre com a senha do mestre.</p><a class="btn btn-light" href="#inicio">Continuar no acervo privado</a></section></div><div class="note-tip">O portal dos jogadores só recebe as notas da lista permitida. O do mestre fica em /mestre/ e sem a senha não pode ser lido. A prévia aqui é só um filtro de tela para você conferir o que a mesa vê.</div>`;}
 function favoriteView(){sidebar('favoritos');crumb('Meus favoritos');document.title='Favoritos · Diário de bordo';const list=favorites.map(x=>byId.get(x)).filter(Boolean);$('main').innerHTML=header('As páginas que você quer por perto.','Seus favoritos são guardados neste navegador.','Seu caderno pessoal')+(list.length?`<div class="document-grid">${list.map(docCard).join('')}</div>`:`<div class="empty-state">${icon('star')}<h2>Marque seu primeiro favorito.</h2><p>Abra uma nota e use o botão Favoritar. As páginas ficam reunidas aqui para sua próxima consulta.</p><a href="#library/regras" class="btn btn-light">Explorar as regras ${icon('arrow')}</a></div>`);}
 function toggleFavorite(id){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];toast(store.set('oprpg-favorites',favorites)?(favorites.includes(id)?'Nota adicionada aos favoritos.':'Nota removida dos favoritos.'):'O navegador não permitiu guardar o favorito.');}

 function article(id,anchor){let d=byId.get(id);if(!d||(preview&&!playerSet.has(id)))return notFound();const inRules=d.category==='regras';sidebar(inRules?'g:'+d.group:d.category);crumb(d.title.length>48?d.title.slice(0,46)+'…':d.title,inRules?[groups[d.group]?.short||'Regras','#library/regras/'+d.group]:[cats[d.category].short,'#library/'+d.category]);document.title=d.title+' · Diário de bordo';let source=d.meta.fonte||(inRules?'Referência de regras':'Nota do projeto');let f=favorites.includes(id);
  $('main').innerHTML=`<div class="article-actions"><a href="${inRules?'#library/regras/'+d.group:isPlayer()&&!playerCats.includes(d.category)?'#inicio':'#library/'+d.category}" class="btn btn-light">← ${inRules?esc(groups[d.group]?.short||'Regras'):cats[d.category].short}</a><button class="btn btn-light" id="favorite-btn">${icon('star')}${f?'Favoritado':'Favoritar'}</button><button class="btn btn-light" id="copy-ref">${icon('copy')}Copiar referência</button><button class="btn btn-light" id="download-note">${icon('download')}Baixar nota</button>${d.category==='personagens'&&(D.characters||[]).find(c=>c.documents.includes(d.id)&&c.pdf)?`<a class="btn btn-light" href="${(D.characters||[]).find(c=>c.documents.includes(d.id)&&c.pdf).pdf}" target="_blank" rel="noopener">${icon('download')}Ficha em PDF</a>`:''}</div><div class="reading-layout"><article class="article"><header class="article-header"><div class="eyebrow">${esc(inRules?groups[d.group]?.name||'Regras':cats[d.category].short)}${d.chapter?' · '+esc(d.chapter):''}</div><h1>${esc(d.title)}</h1><div class="article-meta">${badge(d)}<span class="tag gm">${esc(source)}</span>${d.meta.paginas?`<span class="tag">p. ${esc(d.meta.paginas)}</span>`:''}</div></header><div class="article-body">${d.html}</div>${window.OP_MAP?.aparicoes?.(api,d)||''}<div class="source-path"><strong>Arquivo de origem</strong><br>${esc(d.path)}${d.meta.status?'<br>Estado registrado: '+esc(d.meta.status):''}<br>Acervo gerado do projeto. Alterações são feitas na nota de origem.</div></article><aside class="toc"><h3>Nesta página</h3>${d.headings.filter(x=>!x.title.startsWith('#')).slice(0,30).map(h=>`<a href="#note/${id}/${h.id}" data-scroll="${h.id}">${esc(h.title)}</a>`).join('')}<div class="backlinks"><h3>Notas relacionadas</h3>${d.backlinks.filter(x=>!preview||playerSet.has(x)).slice(0,8).map(x=>`<a href="${link(x)}">${esc(byId.get(x).title)}</a>`).join('')||'<span class="result-count">Novos vínculos aparecerão aqui.</span>'}</div></aside></div>`;
  enhance(document.querySelector('.article-body'));
  $('favorite-btn').onclick=()=>{toggleFavorite(id);let scroll=scrollY;article(id);window.scrollTo(0,scroll);};
  $('download-note').onclick=()=>{const front='---\n'+Object.entries(d.meta).map(([k,v])=>k+': '+JSON.stringify(v)).join('\n')+'\n---\n';let u=URL.createObjectURL(new Blob([front+'\n'+d.body+'\n'],{type:'text/markdown;charset=utf-8'}));let a=document.createElement('a');a.href=u;a.download=d.path.split('/').pop();a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
  $('copy-ref').onclick=async()=>{const ref=d.title+' — '+d.path;try{await navigator.clipboard.writeText(ref);toast('Referência copiada.');}catch{toast('Cópia indisponível. A origem está no rodapé da nota.');}};
  if(anchor){const decoded=decodeURIComponent(anchor);let target=$(decoded)||$(d.headings.find(x=>norm(x.title).replace(/\s/g,'')===norm(decoded).replace(/\s/g,''))?.id);if(target)setTimeout(()=>{target.scrollIntoView({block:'start'});target.classList.add('flash');},0);}
 }
 function notFound(){sidebar('inicio');crumb('Página não encontrada');$('main').innerHTML=`<div class="empty-state">${icon('compass')}<h2>Esta página saiu do mapa.</h2><p>O endereço pode ter mudado após uma edição do acervo${preview?', ou a nota não está liberada para os jogadores':''}. Busque pelo nome da nota.</p><a href="#inicio" class="btn btn-light">Voltar ao diário</a></div>`;}

 /* ---------- Melhorias de leitura: dados clicáveis e tabelas filtráveis ---------- */
 const DICE_RE=/(^|[^\w])(\d{0,2}d(?:4|6|8|10|12|20|100))(\s?[+−-]\s?\d+)?(?![\w])/g;
 function enhance(root){if(!root)return;
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>n.parentElement.closest('a,code,pre,button,th')?NodeFilter.FILTER_REJECT:(/\dd\d|\bd(4|6|8|10|12|20|100)\b/.test(n.nodeValue)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_SKIP)});
  const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  for(const n of nodes){const html=esc(n.nodeValue).replace(DICE_RE,(m,pre,dice,mod)=>`${pre}<button type="button" class="dice-link" data-roll="${dice}${mod?mod.replace(/\s/g,'').replace('−','-'):''}">${dice}${mod||''}</button>`);if(html!==esc(n.nodeValue)){const span=document.createElement('span');span.innerHTML=html;n.replaceWith(...span.childNodes);}}
  root.querySelectorAll('.table-scroll').forEach(wrap=>{const table=wrap.querySelector('table');const rows=[...table.tBodies[0]?.rows||[]];if(rows.length<8||wrap.previousElementSibling?.classList.contains('table-filter'))return;
   const box=document.createElement('div');box.className='table-filter';box.innerHTML=`${icon('search')}<input type="search" placeholder="Filtrar ${rows.length} linhas…" aria-label="Filtrar linhas da tabela"><span class="table-count"></span>`;wrap.before(box);const input=box.querySelector('input'),countEl=box.querySelector('.table-count');
   input.addEventListener('input',()=>{const q=norm(input.value).trim();let n=0;rows.forEach(r=>{const ok=!q||norm(r.textContent).includes(q);r.hidden=!ok;n+=ok;});countEl.textContent=q?`${n} de ${rows.length}`:'';});
   [...table.tHead.rows[0].cells].forEach((th,i)=>{th.classList.add('sortable');th.title='Ordenar por esta coluna';th.addEventListener('click',()=>{const dir=th.dataset.dir==='asc'?'desc':'asc';[...table.tHead.rows[0].cells].forEach(c=>delete c.dataset.dir);th.dataset.dir=dir;const val=r=>{const t=r.cells[i]?.textContent.trim()||'';const m=t.replace(',','.').match(/^-?\d+(\.\d+)?/);return m?[0,parseFloat(m[0])]:[1,norm(t)];};rows.sort((a,b)=>{const x=val(a),y=val(b);const c=x[0]-y[0]||(x[1]<y[1]?-1:x[1]>y[1]?1:0);return dir==='asc'?c:-c;});rows.forEach(r=>table.tBodies[0].appendChild(r));});});});}

 /* ---------- Pré-visualização ao passar o mouse (como no 5etools) ---------- */
 function sectionHtml(d,anchor){const doc=new DOMParser().parseFromString(`<div>${d.html}</div>`,'text/html').body.firstChild;
  if(anchor){const h=doc.querySelector('#'+CSS.escape(anchor));if(h){const level=+h.tagName[1];const parts=[h.outerHTML];let n=h.nextElementSibling;while(n&&!(/^H[1-6]$/.test(n.tagName)&&+n.tagName[1]<=level)&&parts.length<12){parts.push(n.outerHTML);n=n.nextElementSibling;}return parts.join('');}}
  const kids=[...doc.children].filter(el=>!(el.tagName==='P'&&/^fontes?\b/i.test(el.textContent.trim())));return kids.slice(0,4).map(el=>el.outerHTML).join('');}
 let hoverTimer=null,hoverEl=null;
 function setupHover(){if(!matchMedia('(hover: hover) and (pointer: fine)').matches)return;const pop=document.createElement('div');pop.className='hover-preview';pop.hidden=true;document.body.appendChild(pop);
  document.addEventListener('mouseover',e=>{const a=e.target.closest('a[href^="#note/"]');if(!a||a===hoverEl||a.closest('.hover-preview,.search-result,.lib-table,.nav-item,.document-card,.toc,.pane-toc,.quick-card,.rule-card,.crew-row,.step-link'))return;hoverEl=a;clearTimeout(hoverTimer);hoverTimer=setTimeout(()=>{const [,id,anchor]=a.getAttribute('href').slice(1).split('/');const d=byId.get(id);if(!d)return;pop.innerHTML=`<div class="hover-head"><strong>${esc(d.title)}</strong><small>${esc(sourceLabel(d)||cats[d.category].short)}</small></div><div class="article-body">${sectionHtml(d,anchor&&decodeURIComponent(anchor))}</div>`;enhance(pop.querySelector('.article-body'));pop.hidden=false;const r=a.getBoundingClientRect();const w=Math.min(460,innerWidth-24);pop.style.width=w+'px';pop.style.left=Math.max(12,Math.min(r.left,innerWidth-w-12))+'px';const below=r.bottom+8,ph=Math.min(pop.scrollHeight,360);pop.style.top=(below+ph>innerHeight?Math.max(8,r.top-ph-8):below)+'px';},350);});
  document.addEventListener('mouseout',e=>{const a=e.target.closest('a[href^="#note/"]');if(a&&a===hoverEl&&!pop.contains(e.relatedTarget)){clearTimeout(hoverTimer);hoverTimer=setTimeout(()=>{pop.hidden=true;hoverEl=null;},200);}});
  pop.addEventListener('mouseleave',()=>{pop.hidden=true;hoverEl=null;});pop.addEventListener('mouseenter',()=>clearTimeout(hoverTimer));window.addEventListener('hashchange',()=>{pop.hidden=true;hoverEl=null;});}

 /* ---------- Busca global ---------- */
 let searchList=[],searchActive=0;
 function search(){
  const q=norm($('global-search').value).trim(),terms=q.split(/\s+/).filter(Boolean);
  function score(d){let title=norm(d.title),path=norm(d.path),heads=norm(d.headings.map(h=>h.title).join(' '));let n=title.includes(q)?60:0;for(let t of terms){if(title.includes(t))n+=20;if(heads.includes(t))n+=12;}if(d.category==='regras'&&d.group!=='guia'&&d.group!=='bestiario')n+=9;if(path.includes('auditoria'))n-=12;if(path.includes('tecnicas e condicoes')&&terms.some(t=>['atordoado','sangramento','envenenado','queimado','condicoes','incapacitado','caido','exaustao'].includes(t)))n+=18;return n;}
  const all=terms.length?docs.filter(d=>terms.every(t=>d.search.includes(t))).sort((a,b)=>score(b)-score(a)||a.title.localeCompare(b.title,'pt-BR')):ruleFeatures.map(([n])=>byId.get(D.shortcuts[n])).filter(Boolean);
  searchList=all.slice(0,60);searchActive=0;
  const mark=s=>{let out=esc(s);for(const t of terms.filter(t=>t.length>1)){out=out.replace(new RegExp('('+[...t].map(c=>{const base=c.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');return base==='a'?'[aàáâã]':base==='e'?'[eéê]':base==='i'?'[ií]':base==='o'?'[oóôõ]':base==='u'?'[uú]':base==='c'?'[cç]':base;}).join('')+')','gi'),'<mark>$1</mark>');}return out;};
  function snippet(d){if(!terms.length)return d.summary;const body=d.body.split('\n').filter(l=>!/^fontes?\b/i.test(norm(l).trim())).join('\n');let i=norm(body).indexOf(terms[0]);if(i<0)return d.summary;return (i>50?'…':'')+body.slice(Math.max(0,i-50),i+160).replace(/[\[\]#*>`|]/g,' ').replace(/\s+/g,' ')+(body.length>i+160?'…':'');}
  const sectionFor=d=>{if(!terms.length)return null;const h=d.headings.find(h=>terms.every(t=>norm(h.title).includes(t)))||d.headings.find(h=>norm(h.title).includes(terms[0]));return h&&!norm(d.title).includes(terms[0])?h:null;};
  const label=d=>d.category==='regras'?groups[d.group]?.name||'Regras':cats[d.category].short;
  const order=[...new Set(searchList.map(label))];
  $('search-results').innerHTML=(terms.length?`<div class="search-help">${all.length} ${all.length===1?'nota encontrada':'notas encontradas'}${all.length>60?' · exibindo as 60 mais relevantes':''} · ↑ ↓ e Enter</div>`:'')+(order.map(g=>`<div class="search-group">${esc(g)}</div>`+searchList.filter(d=>label(d)===g).map(d=>{const sec=sectionFor(d);return `<a href="${link(d.id,sec?.id)}" class="search-result" data-i="${searchList.indexOf(d)}"><strong>${mark(d.title)}${sec?` <span class="search-section">› ${mark(sec.title)}</span>`:''}</strong><small>${mark(snippet(d))}</small>${d.book?`<small class="search-source">${esc(sourceLabel(d))}</small>`:''}</a>`;}).join('')).join('')||'<div class="empty-state"><p>Nenhuma nota encontrada. Tente menos palavras.</p></div>');
  highlightSearch();}
 function highlightSearch(){document.querySelectorAll('#search-results .search-result').forEach(a=>a.classList.toggle('active',+a.dataset.i===searchActive));document.querySelector('#search-results .search-result.active')?.scrollIntoView({block:'nearest'});}

 /* ---------- Roteamento ---------- */
 function render(){const hash=location.hash.slice(1);const parts=hash.split('/');document.body.classList.remove('menu-open');$('menu-toggle').setAttribute('aria-expanded','false');window.OP_TOOLS?.leave?.();window.OP_MAP?.leave?.();document.body.classList.toggle('map-page',parts[0]==='mapa'&&!!window.OP_MAP);
  if(!hash||hash==='inicio'||hash==='main')home();
  else if(parts[0]==='library')library(parts[1],parts[2]==='tudo'?'':parts[2],parts[3]);
  else if(hash==='favoritos')favoriteView();else if(hash==='acessos')accessView();else if(hash==='comece')startHere();
  else if(['mesa','iniciativa','bestiario','referencia','fichas'].includes(parts[0])&&window.OP_TOOLS&&(parts[0]==='referencia'||!isPlayer())){sidebar(parts[0]);crumb({mesa:'Tela do mestre',iniciativa:'Iniciativa',bestiario:'Bestiário',referencia:'Referência rápida',fichas:'Fichas na mesa'}[parts[0]]);window.OP_TOOLS.mount(parts[0],$('main'),api,parts[1]);}
  else if(parts[0]==='gravacoes'&&window.OP_SESSIONS&&!isPlayer()){const r=(D.recordings||[]).find(x=>x.id===decodeURIComponent(parts[1]||''));sidebar('gravacoes');crumb(r?'Sessão '+String(r.session).padStart(2,'0'):'Gravações das sessões',parts[1]?['Gravações das sessões','#gravacoes']:null);window.OP_SESSIONS.mount($('main'),api,parts[1],parts[2]);}
  else if(parts[0]==='mapa'&&window.OP_MAP){sidebar('mapa');crumb('Mapa do mundo');window.OP_MAP.mount($('main'),api,parts[1],parts[2]);}
  else if(parts[0]==='jornal'&&window.OP_JOURNAL){sidebar('jornal');crumb(parts[1]==='procurados'?'Procurados':parts[1]==='edicoes'?'Todas as edições':parts[1]?'Edição nº '+parts[1]:"Jornal News Coo's",parts[1]?["Jornal News Coo's",'#jornal']:null);window.OP_JOURNAL.mount($('main'),api,parts[1]);}
  else if(parts[0]==='criar-personagem'&&window.OP_CREATOR){const p=isPlayer();sidebar(p?'criar':'oficina');crumb('Criar personagem',p?null:['Oficina','#library/oficina']);window.OP_CREATOR.mount($('main'),D,{player:p,shared:parts[1]==='ficha'?parts[2]:null});}
  else if(parts[0]==='criadores'&&window.OP_FORGE){sidebar('criadores');crumb('Criadores');window.OP_FORGE.mount($('main'),D,{player:isPlayer(),type:parts[1],shared:parts[2]==='link'?parts[3]:null});}
  else if(parts[0]==='note')article(parts[1],parts[2]);else notFound();
  if(parts[0]!=='note'||!parts[2])window.scrollTo(0,0);}
 /* O que tools.js precisa do portal. */
 const api={D,get docs(){return docs;},byId,byStem,esc,norm,icon,link,header,enhance,sectionHtml,store,toast,isPlayer,groups};

 const dialog=$('search-dialog');function openSearch(){dialog.showModal();search();$('global-search').focus();}
 $('search-icon').innerHTML=icon('search');$('dialog-search-icon').innerHTML=icon('search');$('refresh').innerHTML=icon('refresh');$('menu-toggle').innerHTML=icon('menu');$('refresh').title='Atualizar o acervo (recarrega as notas do Vault)';$('refresh').setAttribute('aria-label','Atualizar o acervo');$('refresh').onclick=()=>location.reload();$('search-trigger').onclick=openSearch;$('close-search').onclick=()=>dialog.close();$('global-search').oninput=search;
 $('global-search').addEventListener('keydown',e=>{if(!searchList.length)return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();searchActive=Math.max(0,Math.min(searchList.length-1,searchActive+(e.key==='ArrowDown'?1:-1)));highlightSearch();}if(e.key==='Enter'){e.preventDefault();const a=document.querySelector('#search-results .search-result.active');if(a){dialog.close();location.hash=a.getAttribute('href');}}});
 $('search-results').addEventListener('click',e=>{if(e.target.closest('a'))dialog.close();});dialog.addEventListener('click',e=>{if(e.target===dialog){let r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
 document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if(!dialog.open)openSearch();}});
 $('menu-toggle').onclick=()=>{let on=document.body.classList.toggle('menu-open');$('menu-toggle').setAttribute('aria-expanded',String(on));};document.addEventListener('click',e=>{if(document.body.classList.contains('menu-open')&&!e.target.closest('#sidebar')&&!e.target.closest('#menu-toggle')){document.body.classList.remove('menu-open');$('menu-toggle').setAttribute('aria-expanded','false');}});
 document.addEventListener('click',e=>{const on=e.target.closest('[data-preview-on]'),off=e.target.closest('[data-preview-off]');if(!on&&!off)return;preview=!!on;try{sessionStorage.setItem('oprpg-player-preview',preview?'1':'0');}catch{}applyPreview();toast(preview?'Prévia do jogador ativada.':'De volta ao acervo do mestre.');location.hash='#inicio';render();});
 document.addEventListener('click',e=>{if(!e.target.closest('[data-logout]')||!window.OP_GATE)return;try{localStorage.removeItem('oprpg-chave-'+window.OP_GATE.area);}catch{}location.reload();});
 /* Modo escuro: escolha guardada no navegador; sem escolha, segue o sistema. */
 const themeBtn=document.createElement('button');themeBtn.className='icon-button';themeBtn.id='theme-toggle';const applyTheme=t=>{document.documentElement.dataset.theme=t;themeBtn.innerHTML=icon(t==='dark'?'sun':'moon');themeBtn.title=t==='dark'?'Usar tema claro':'Usar tema escuro';themeBtn.setAttribute('aria-label',themeBtn.title);};
 applyTheme(store.get('oprpg-theme',null)||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'));themeBtn.onclick=()=>{const t=document.documentElement.dataset.theme==='dark'?'light':'dark';store.set('oprpg-theme',t);applyTheme(t);};
 const diceBtn=document.createElement('button');diceBtn.className='icon-button';diceBtn.id='dice-toggle';diceBtn.innerHTML=icon('dice');diceBtn.title='Rolar dados';diceBtn.setAttribute('aria-label','Rolar dados');diceBtn.onclick=()=>window.OP_TOOLS?.toggleDice();
 $('refresh').before(diceBtn,themeBtn);
 const avatar=document.querySelector('.avatar');if(D.audience==='player'){avatar.textContent='T';avatar.title='Área dos jogadores';}else{const b=document.createElement('button');b.className='avatar avatar-button';b.textContent='V';b.title='Alternar entre o acervo do mestre e a prévia do jogador';b.setAttribute('aria-label',b.title);b.onclick=()=>{preview=!preview;try{sessionStorage.setItem('oprpg-player-preview',preview?'1':'0');}catch{}applyPreview();toast(preview?'Prévia do jogador ativada.':'De volta ao acervo do mestre.');location.hash='#inicio';render();};avatar.replaceWith(b);}
 $('updated').textContent='Acervo atualizado em '+new Date(D.generatedAt).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'});
 setupHover();
 window.addEventListener('hashchange',render);render();
})();
